#include "core_shaders.h" // generated by CMake: shaders/*.{vert,frag} with the conventions include, baked by qsb

#include <rhi/qrhi.h>
#include <rhi/qshader.h>

#include <QtCore/QHash>
#include <QtCore/QPointer>
#include <QtGui/QColor>
#include <QtQuick/QQuickWindow>

namespace srpss_core {

namespace {

// std140, the pattern pass's block (shaders/pattern.frag).
struct PatternBlock
{
    float targetSize[4]; // xy: the target in pixels
    float pattern[4];    // x: SurfacePattern
};
static_assert(sizeof(PatternBlock) == 32, "std140 Pattern block");

// A triangle over the whole viewport in clip space (no matrix: the content depends only on the texel it lands on).
constexpr float kFullTriangle[6] = { -1.0f, -1.0f, 3.0f, -1.0f, -1.0f, 3.0f };
constexpr int kTargetObjects = 3; // texture, render target, pass descriptor
constexpr int kPassObjects = 5;   // three buffers, bindings, pipeline

QAtomicInteger<int> g_liveSurfaces { 0 };
QAtomicInteger<int> g_liveResources { 0 };

QShader shaderFrom(const unsigned char *data, unsigned int size)
{
    return QShader::fromSerialized(QByteArray(reinterpret_cast<const char *>(data), int(size)));
}

struct RegistryEntry
{
    QPointer<QQuickWindow> window;
    std::weak_ptr<WindowSurfaces> surfaces;
};

QMutex &registryMutex()
{
    static QMutex mutex;
    return mutex;
}

QHash<QQuickWindow *, RegistryEntry> &registry()
{
    static QHash<QQuickWindow *, RegistryEntry> entries;
    return entries;
}

} // namespace

bool parseSurfacePattern(const QString &text, SurfacePattern *out)
{
    if (text == QLatin1String("texel_id")) {
        *out = SurfacePattern::TexelIdentity;
        return true;
    }
    if (text == QLatin1String("white")) {
        *out = SurfacePattern::White;
        return true;
    }
    return false;
}

QString surfacePatternName(SurfacePattern pattern)
{
    return pattern == SurfacePattern::White ? QStringLiteral("white") : QStringLiteral("texel_id");
}

// ------------------------------------------------------------------------------------------------- Surface

struct Surface::Resources
{
    QRhi *rhi = nullptr;
    ColorTarget target;
    std::unique_ptr<QRhiBuffer> vertices;
    std::unique_ptr<QRhiBuffer> uniforms;
    std::unique_ptr<QRhiBuffer> conventions;
    std::unique_ptr<QRhiShaderResourceBindings> srb;
    std::unique_ptr<QRhiGraphicsPipeline> pipeline;
    bool staticUploaded = false;
};

Surface::Surface()
{
    g_liveSurfaces.fetchAndAddRelaxed(1);
}

Surface::~Surface()
{
    release();
    g_liveSurfaces.fetchAndAddRelaxed(-1);
}

int Surface::liveSurfaces()
{
    return g_liveSurfaces.loadRelaxed();
}

int Surface::liveResourcesTotal()
{
    return g_liveResources.loadRelaxed();
}

void Surface::setLive(int count)
{
    const int before = m_live.fetchAndStoreRelaxed(count);
    g_liveResources.fetchAndAddRelaxed(count - before);
}

QRhiTexture *Surface::texture() const
{
    return m_res ? m_res->target.texture.get() : nullptr;
}

QSize Surface::pixelSize() const
{
    return (m_res && m_res->target.texture) ? m_res->target.texture->pixelSize() : QSize();
}

QString Surface::lastPrime() const
{
    QMutexLocker lock(&m_mutex);
    return m_lastPrime;
}

void Surface::setPattern(SurfacePattern pattern)
{
    if (pattern == m_pattern)
        return;
    m_pattern = pattern;
    m_dirty.storeRelease(1);
}

bool Surface::ensureTarget(QRhi *rhi, const QSize &pixels, QString *error)
{
    if (!rhi || pixels.width() < 1 || pixels.height() < 1) {
        *error = QStringLiteral("a surface needs a QRhi and a size of at least one pixel");
        return false;
    }
    if (m_res && m_res->rhi != rhi) {
        // The node (and with it this surface) goes with Qt's scene graph, so a second QRhi means a broken lifetime.
        *error = QStringLiteral("the surface was created on another QRhi");
        return false;
    }
    if (!m_res) {
        auto res = std::make_unique<Resources>();
        res->rhi = rhi;
        if (!createColorTarget(rhi, pixels, QByteArrayLiteral("srpss core surface"), &res->target, error))
            return false;
        m_res = std::move(res);
        setLive(kTargetObjects);
        m_dirty.storeRelease(1);
        return true;
    }
    if (m_res->target.texture->pixelSize() == pixels)
        return true;
    // The same objects at the new size (the render pass descriptor and the pipeline stay compatible: same format).
    m_res->target.texture->setPixelSize(pixels);
    if (!m_res->target.texture->create() || !m_res->target.renderTarget->create()) {
        *error = QStringLiteral("the surface target could not be resized to %1 x %2").arg(pixels.width()).arg(
            pixels.height());
        release();
        return false;
    }
    m_dirty.storeRelease(1);
    return true;
}

bool Surface::ensurePass(QString *error)
{
    Resources &r = *m_res;
    if (r.pipeline)
        return true;
    QRhi *rhi = r.rhi;
    const QShader vs = shaderFrom(pattern_vert_qsb, pattern_vert_qsb_size);
    const QShader fs = shaderFrom(pattern_frag_qsb, pattern_frag_qsb_size);
    if (!vs.isValid() || !fs.isValid()) {
        *error = QStringLiteral("the pattern pass's baked shaders are not valid");
        return false;
    }
    r.vertices.reset(rhi->newBuffer(QRhiBuffer::Immutable, QRhiBuffer::VertexBuffer, sizeof(kFullTriangle)));
    r.uniforms.reset(rhi->newBuffer(QRhiBuffer::Dynamic, QRhiBuffer::UniformBuffer, sizeof(PatternBlock)));
    r.conventions.reset(rhi->newBuffer(QRhiBuffer::Dynamic, QRhiBuffer::UniformBuffer, sizeof(ConventionsBlock)));
    r.vertices->setName(QByteArrayLiteral("srpss core surface pattern vertices"));
    r.uniforms->setName(QByteArrayLiteral("srpss core surface pattern block"));
    r.conventions->setName(QByteArrayLiteral("srpss core surface conventions block"));
    if (!r.vertices->create() || !r.uniforms->create() || !r.conventions->create()) {
        *error = QStringLiteral("the pattern pass's buffers could not be created");
        return false;
    }
    r.srb.reset(rhi->newShaderResourceBindings());
    r.srb->setName(QByteArrayLiteral("srpss core surface pattern bindings"));
    r.srb->setBindings({
        QRhiShaderResourceBinding::uniformBuffer(0, QRhiShaderResourceBinding::FragmentStage, r.uniforms.get()),
        QRhiShaderResourceBinding::uniformBuffer(kConventionsBinding, QRhiShaderResourceBinding::FragmentStage,
                                                 r.conventions.get()) });
    if (!r.srb->create()) {
        *error = QStringLiteral("the pattern pass's bindings could not be created");
        return false;
    }
    r.pipeline.reset(rhi->newGraphicsPipeline());
    r.pipeline->setName(QByteArrayLiteral("srpss core surface pattern"));
    r.pipeline->setTargetBlends({ QRhiGraphicsPipeline::TargetBlend() }); // blending off: every texel is written
    r.pipeline->setShaderStages({ { QRhiShaderStage::Vertex, vs }, { QRhiShaderStage::Fragment, fs } });
    QRhiVertexInputLayout layout;
    layout.setBindings({ { quint32(2 * sizeof(float)) } });
    layout.setAttributes({ { 0, 0, QRhiVertexInputAttribute::Float2, 0 } });
    r.pipeline->setVertexInputLayout(layout);
    r.pipeline->setCullMode(QRhiGraphicsPipeline::None);
    r.pipeline->setShaderResourceBindings(r.srb.get());
    r.pipeline->setRenderPassDescriptor(r.target.renderPass.get());
    if (!r.pipeline->create()) {
        *error = QStringLiteral("the pattern pass's pipeline could not be created");
        r.pipeline.reset();
        return false;
    }
    setLive(kTargetObjects + kPassObjects);
    return true;
}

bool Surface::record(QRhi *rhi, QRhiCommandBuffer *cb, bool *recorded, QString *error)
{
    *recorded = false;
    if (!dirty())
        return true; // at rest: the target keeps what it holds
    if (!m_res || !m_res->target.isValid()) {
        *error = QStringLiteral("the surface has no target");
        return false;
    }
    if (m_res->rhi != rhi || !cb) {
        *error = QStringLiteral("the surface is recorded on another QRhi, or with no command buffer");
        return false;
    }
    if (!ensurePass(error))
        return false;
    Resources &r = *m_res;
    QRhiTexture *texture = r.target.texture.get();
    const QString prime = primeForLoad(rhi, cb, texture); // rule C: Qt Quick sampled it since our last pass
    QRhiResourceUpdateBatch *updates = rhi->nextResourceUpdateBatch();
    if (!r.staticUploaded) {
        updates->uploadStaticBuffer(r.vertices.get(), kFullTriangle);
        const ConventionsBlock block = targetConventions(rhi); // F1, F2: the block of a target the core owns
        updates->updateDynamicBuffer(r.conventions.get(), 0, sizeof(ConventionsBlock), &block);
        r.staticUploaded = true;
    }
    const QSize size = texture->pixelSize();
    PatternBlock block = {};
    block.targetSize[0] = float(size.width());
    block.targetSize[1] = float(size.height());
    block.pattern[0] = float(int(m_pattern));
    updates->updateDynamicBuffer(r.uniforms.get(), 0, sizeof(PatternBlock), &block);
    // The target keeps its contents (rule B): the triangle covers every texel with blending off, so nothing earlier
    // survives the pass.
    cb->beginPass(r.target.renderTarget.get(), QColor(0, 0, 0, 0), { 1.0f, 0 }, updates);
    cb->setGraphicsPipeline(r.pipeline.get());
    cb->setViewport(QRhiViewport(0, 0, float(size.width()), float(size.height())));
    cb->setShaderResources();
    const QRhiCommandBuffer::VertexInput input(r.vertices.get(), 0);
    cb->setVertexInput(0, 1, &input);
    cb->draw(3);
    cb->endPass();
    m_dirty.storeRelease(0);
    m_passes.fetchAndAddRelaxed(1);
    *recorded = true;
    QMutexLocker lock(&m_mutex);
    m_lastPrime = prime;
    return true;
}

void Surface::release()
{
    if (!m_res)
        return;
    m_res->pipeline.reset();
    m_res->srb.reset();
    m_res->conventions.reset();
    m_res->uniforms.reset();
    m_res->vertices.reset();
    m_res->target.reset();
    m_res.reset();
    setLive(0);
    m_dirty.storeRelease(1);
}

// ------------------------------------------------------------------------------------------------- WindowSurfaces

std::shared_ptr<WindowSurfaces> WindowSurfaces::forWindow(QQuickWindow *window)
{
    QMutexLocker lock(&registryMutex());
    RegistryEntry &entry = registry()[window];
    std::shared_ptr<WindowSurfaces> surfaces = entry.surfaces.lock();
    if (!surfaces || entry.window.isNull()) {
        surfaces = std::make_shared<WindowSurfaces>();
        entry.window = window;
        entry.surfaces = surfaces;
    }
    return surfaces;
}

void WindowSurfaces::driverAttached()
{
    QMutexLocker lock(&m_mutex);
    ++m_drivers;
}

void WindowSurfaces::driverDetached()
{
    QMutexLocker lock(&m_mutex);
    if (m_drivers > 0)
        --m_drivers;
}

int WindowSurfaces::drivers() const
{
    QMutexLocker lock(&m_mutex);
    return m_drivers;
}

void WindowSurfaces::add(const std::shared_ptr<Surface> &surface)
{
    QMutexLocker lock(&m_mutex);
    for (const std::shared_ptr<Surface> &s : m_surfaces) {
        if (s == surface)
            return;
    }
    m_surfaces.append(surface);
}

void WindowSurfaces::remove(const Surface *surface)
{
    QMutexLocker lock(&m_mutex);
    for (qsizetype i = 0; i < m_surfaces.size(); ++i) {
        if (m_surfaces.at(i).get() == surface) {
            m_surfaces.removeAt(i);
            return;
        }
    }
}

int WindowSurfaces::count() const
{
    QMutexLocker lock(&m_mutex);
    return int(m_surfaces.size());
}

QList<std::shared_ptr<Surface>> WindowSurfaces::dirtySurfaces() const
{
    QList<std::shared_ptr<Surface>> dirty;
    QMutexLocker lock(&m_mutex);
    for (const std::shared_ptr<Surface> &s : m_surfaces) {
        if (s->dirty())
            dirty.append(s);
    }
    return dirty;
}

} // namespace srpss_core
